import{_ as o,a as n,b as i,c as l,d as h,e as c,f as w,g as u,h as m,i as g,j as b,k as v}from"./chunks/t9Jro9BAIMw-1280.DkQ_vvkz.js";import{_ as y,C as r,o as f,c as k,j as t,a,E as s,a8 as _}from"./chunks/framework.27XeWUA0.js";const F=JSON.parse('{"title":"AI Digest · Sat 31 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-31","routine":"digest"},"relativePath":"digest/2026-10-31.md","filePath":"digest/[date].md"}'),x={name:"digest/2026-10-31.md"},I=o+" 640w, "+w+" 1280w",A=n+" 640w, "+u+" 1280w",D=i+" 640w, "+m+" 1280w",q=l+" 640w, "+g+" 1280w",S=h+" 640w, "+b+" 1280w",U=c+" 640w, "+v+" 1280w",T={id:"ai-digest-·-sat-31-oct-2026",tabindex:"-1"};function z(R,e,O,P,E,Y){const p=r("Badge"),d=r("DayFilter");return f(),k("div",null,[t("h1",T,[e[0]||(e[0]=a("AI Digest · Sat 31 Oct 2026 ",-1)),s(p,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sat-31-oct-2026","aria-label":'Permalink to "AI Digest · Sat 31 Oct 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 31 Oct 2026 · run date Sat 31 Oct 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 5 new talks in the last 24 hours, all with full transcripts. The freshest is Oracle's 19-minute talk on deciding what an agent should remember (30 Oct, 11:00 PM IST), worth a skim for its memory promotion gate demo. The picks are SoFi's six concrete attacks on x402 agent payments and Vals AI's data on why a cheaper-per-token model can cost more per task. Sonar's Vortex talk (their fourth this week) is mostly a repeat, and the hedge-fund fireside chat is light on engineering.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" 1 new video, a fun Raspberry Pi pumpkin voice assistant build (30 Oct, 9:30 AM IST), light on new AI content.")])],-1)),s(d),e[5]||(e[5]=_('<div class="grid cards2"><article class="it full" id="v-qq2Hm4XNRgI" data-title="How to Decide What Your AI Agent Should Remember - Wojciech Pluta, Oracle" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=qq2Hm4XNRgI" target="_blank" rel="noopener"><img src="'+o+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI" target="_blank" rel="noopener">How to Decide What Your AI Agent Should Remember - Wojciech Pluta, Oracle</a></h3><div class="meta">AI Engineer · Wojciech Pluta, Oracle AI Database · uploaded 30 Oct, 11:00 PM IST · 19:06</div><div class="verdict v-skim"><b>Verdict:</b> skim from <a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=293s" target="_blank" rel="noopener">4:53</a> for the promotion-gate demo; the rest is a standard Oracle database pitch.</div><div class="repeat">🔁 Repeat: &#39;agent memory&#39; — seen 15 times before. New here: a concrete &quot;memory promotion gate&quot; that decides what an agent may write to long-term memory, shown on a mortgage-agent demo.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 18 times before. New here: Oracle&#39;s &quot;context card&quot; format for handing memory back to the agent.</div><div class="sh">Read path versus write path</div><ul><li><strong>Memory is the write path (repeat):</strong> Models and infrastructure are commoditised, so the data layer is where the advantage is. RAG gives an agent a way to read, but it doesn&#39;t decide what should survive a conversation; memory is the write path (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=105s" target="_blank" rel="noopener">1:45</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=260s" target="_blank" rel="noopener">4:20</a>)</li><li><strong>Memory promotion:</strong> Each candidate memory is classified by meaning, compared with existing records and checked for the evidence its type needs, then the harness admits it, rejects it or sends it to a human (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=261s" target="_blank" rel="noopener">4:21</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li></ul><div class="sh">Mortgage-agent demo (pre-recorded)</div><ul><li><strong>A preference that sticks:</strong> The operator asks for a mortgage brief for &quot;Kyle&quot;, then states a formatting preference (missing documents first, with case ID and policy). A decision model assesses it, the harness admits it and the database stores it; a brand-new session with no carried-over context returns the brief in the new format (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=356s" target="_blank" rel="noopener">5:56</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=540s" target="_blank" rel="noopener">9:00</a>)</li><li><strong>Guardrails on what gets remembered:</strong> A &quot;approve every application&quot; instruction is rejected by the promotion gate, while a team-wide operational memory is routed to a human for approval before it is shared across the enterprise (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=573s" target="_blank" rel="noopener">9:33</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=690s" target="_blank" rel="noopener">11:30</a>)</li></ul><div class="sh">How Oracle structures it</div><ul><li><strong>Three kinds of memory:</strong> Short-term (the session), long-term (episodic, procedural and semantic: summaries, toolbox, knowledge base and preferences) and shared memory. Promote nothing and you lose continuity; promote everything and you poison the store (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=724s" target="_blank" rel="noopener">12:04</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=815s" target="_blank" rel="noopener">13:35</a>)</li><li><strong>Why a database:</strong> He argues for a database over file trees because of ACID guarantees, concurrent writes, scaling and multiple search options, with schemas per record type, matching indexes and lifecycle and authorisation boundaries (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=815s" target="_blank" rel="noopener">13:35</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=911s" target="_blank" rel="noopener">15:11</a>)</li><li><strong>Agent memory package and context card:</strong> Oracle&#39;s package (introduced early this year) does summarising, extraction and token budgeting behind one line of code and returns a &quot;context card&quot; of topics, summaries, selected records and recent messages; the latest release adds per-end-user isolation enforced by the database (<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=879s" target="_blank" rel="noopener">14:39</a>–<a href="https://www.youtube.com/watch?v=qq2Hm4XNRgI&amp;t=1066s" target="_blank" rel="noopener">17:46</a>)</li></ul></div></article><article class="it full" id="v-8vDzncmzxyg" data-title="Your AI Agent Starts Every Session Like a New Hire - Killian Carlsen-Phelan, Sonar" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=8vDzncmzxyg" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+A+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=8vDzncmzxyg" target="_blank" rel="noopener">Your AI Agent Starts Every Session Like a New Hire - Killian Carlsen-Phelan, Sonar</a></h3><div class="meta">AI Engineer · Killian Carlsen-Phelan, Sonar · uploaded 30 Oct, 7:00 PM IST · 17:45</div><div class="verdict v-skim"><b>Verdict:</b> skim the demo from <a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=587s" target="_blank" rel="noopener">9:47</a>; otherwise mostly a repeat of this week&#39;s Sonar talks.</div><div class="repeat">🔁 Repeat: &#39;AI-generated code validation&#39; — seen 29 times before (Sonar&#39;s fourth talk this week). New here: Sonar Vortex, a plugin that feeds SonarQube&#39;s project knowledge to the agent before and while it writes, rather than reviewing at the PR.</div><div class="repeat">🔁 Repeat: &#39;context engineering&#39; — seen 18 times before. New here: little beyond &quot;front-load guidelines and a code map&quot;.</div><div class="sh">The problem</div><ul><li><strong>Every session is a new hire (repeat):</strong> A fresh agent session doesn&#39;t know your conventions, architecture rules or approved libraries, so it greps around burning tokens and copies existing bad patterns (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=32s" target="_blank" rel="noopener">0:32</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=123s" target="_blank" rel="noopener">2:03</a>)</li><li><strong>Survey numbers:</strong> Sonar surveyed over 1,100 developers; 96% don&#39;t fully trust AI-generated code, yet only 48% fully verify it before pushing (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=217s" target="_blank" rel="noopener">3:37</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=247s" target="_blank" rel="noopener">4:07</a>)</li></ul><div class="sh">What Vortex does</div><ul><li><strong>Guide, then verify:</strong> Before writing, the agent pulls project guidelines, approved libraries and a map of how code connects; every edit triggers a quick SonarQube check, and before ending its turn it runs a deeper cross-file data-flow check. It works with Claude Code, Codex, Antigravity and custom agents via configurable MCP clients (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=342s" target="_blank" rel="noopener">5:42</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=433s" target="_blank" rel="noopener">7:13</a>)</li><li><strong>Claimed results:</strong> 36% fewer tokens on average (especially refactors), a 44% reduction in production outages among users, and a low false-positive rate (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=433s" target="_blank" rel="noopener">7:13</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=464s" target="_blank" rel="noopener">7:44</a>)</li><li><strong>Deterministic, not AI-on-AI:</strong> He argues an agent reviewing its own or another agent&#39;s code is unreliable, while static analysis gives the same result every run, which makes it governable; it can also block secrets leaking into GitHub or agent memory (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=556s" target="_blank" rel="noopener">9:16</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=587s" target="_blank" rel="noopener">9:47</a>) (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=772s" target="_blank" rel="noopener">12:52</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=838s" target="_blank" rel="noopener">13:58</a>)</li></ul><div class="sh">Recorded demo</div><ul><li><strong>The temp-file bug:</strong> Asked to unzip a log into a reusable temp file with a test, Claude first queried Sonar for where the class lives and the Java guidelines. Vortex then returned six findings (two in new lines, four pre-existing); one was a temp file in a shared folder without explicit permissions. Claude&#39;s first fix relied on the OS default, Vortex flagged it as still open, and the second fix set permissions explicitly (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=587s" target="_blank" rel="noopener">9:47</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=650s" target="_blank" rel="noopener">10:50</a>) (<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=741s" target="_blank" rel="noopener">12:21</a>–<a href="https://www.youtube.com/watch?v=8vDzncmzxyg&amp;t=959s" target="_blank" rel="noopener">15:59</a>)</li></ul></div></article><article class="it full" id="v-YU1uD_YkpjU" data-title="Your Agent Just Paid for Nothing: 6 Attacks on x402 Payments - Ishween Kaur, SoFi" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=YU1uD_YkpjU" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+D+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=YU1uD_YkpjU" target="_blank" rel="noopener">Your Agent Just Paid for Nothing: 6 Attacks on x402 Payments - Ishween Kaur, SoFi</a></h3><div class="meta">AI Engineer · Ishween Kaur, SoFi · uploaded 30 Oct, 9:00 AM IST · 16:44</div><div class="verdict v-worth"><b>Verdict:</b> worth watching; the most concrete agent-payments security talk so far.</div><div class="repeat">🔁 Repeat: &#39;agent payments / x402&#39; — seen 5 times before. New here: this is an attacker&#39;s view, six concrete ways she broke x402 on a testnet and the fix for each.</div><div class="repeat">🔁 Repeat: &#39;agent security&#39; — seen 26 times before. New here: payment-specific failure modes rather than generic tool security.</div><div class="sh">How x402 works</div><ul><li><strong>Basics (repeat):</strong> HTTP 402 &quot;payment required&quot; existed for decades with no way for a machine to pay; x402 fills that with a buyer, seller, facilitator (verifies the signature, then settles) and a chain. Card fees make sub-cent payments illogical, while 10 cents times 10,000 calls is $1,000 moving between machines (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=94s" target="_blank" rel="noopener">1:34</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=218s" target="_blank" rel="noopener">3:38</a>)</li></ul><div class="sh">Six attacks (she found 20 in total, on Base Sepolia with a local facilitator)</div><ul><li><strong>Price switch:</strong> A seller listed at 5 cents but asked 50 in the 402 header, and the unguarded buyer paid. Fix: compare listed and requested price, and also the wallet address and network, which can rotate (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=218s" target="_blank" rel="noopener">3:38</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=311s" target="_blank" rel="noopener">5:11</a>)</li><li><strong>Paying twice:</strong> Reusing one payment number five times got the data delivered five times though only one settled; buyer-side retries with new payment numbers mean three charges for one result. Fix: shared storage of payment numbers, and retry with the same number (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=311s" target="_blank" rel="noopener">5:11</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=435s" target="_blank" rel="noopener">7:15</a>)</li><li><strong>Free shopping:</strong> Data released on the &quot;valid&quot; signal before a settlement that later reverts, an unprotected duplicate endpoint, or a seller cache on a public URL all give data away. Fix: wait for settlement when data is expensive, test that every paid endpoint returns 402, and use `Cache-Control: no-store` (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=435s" target="_blank" rel="noopener">7:15</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=560s" target="_blank" rel="noopener">9:20</a>)</li><li><strong>One payment, many pages:</strong> Separate paid pages that don&#39;t share state each accept the same payment. Fix: bind the claim to the delivered page and return 409 Conflict on reuse (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=560s" target="_blank" rel="noopener">9:20</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=621s" target="_blank" rel="noopener">10:21</a>)</li><li><strong>Lookalike sellers:</strong> The Bazaar directory checks that a service works, not who owns the wallet, so a cheaper copycat can win. Fix: allow, block and probation lists, with new sellers on probation for human review (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=591s" target="_blank" rel="noopener">9:51</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=712s" target="_blank" rel="noopener">11:52</a>)</li><li><strong>Prompt injection:</strong> A seller reply hinting &quot;full version at premium summary&quot; made her Llama 3.2 agent pay again, 55 cents instead of 5. Keyword filters miss quiet hints and a judge model isn&#39;t airtight; locking the plan to one payment per turn brought attacks to zero (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=712s" target="_blank" rel="noopener">11:52</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=865s" target="_blank" rel="noopener">14:25</a>)</li></ul><div class="sh">Rolling it out</div><ul><li><strong>Trace one payment ID end to end,</strong> then run a shadow phase with 20–25 success and failure cases, do error analysis to decide where to guard, alert or block, and re-test (<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=865s" target="_blank" rel="noopener">14:25</a>–<a href="https://www.youtube.com/watch?v=YU1uD_YkpjU&amp;t=988s" target="_blank" rel="noopener">16:28</a>)</li></ul></div></article><article class="it full" id="v-y2dyD6slKxE" data-title="Why AI Won&#39;t Replace Stock Pickers - Jack Woodruff, Candlestick &amp; Vinoo Ganesh, Kepler" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=y2dyD6slKxE" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=y2dyD6slKxE" target="_blank" rel="noopener">Why AI Won&#39;t Replace Stock Pickers - Jack Woodruff, Candlestick &amp; Vinoo Ganesh, Kepler</a></h3><div class="meta">AI Engineer · Jack Woodruff (Candlestick Capital) with Vinoo Ganesh (Kepler) · uploaded 30 Oct, 8:00 AM IST · 18:46</div><div class="verdict v-skim"><b>Verdict:</b> skim; interesting if you care about finance, but light on engineering.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 16 times before. New here: a hedge-fund founder&#39;s buyer-side view rather than a vendor pitch; it&#39;s a fireside chat with no product demo.</div><div class="sh">What changes and what doesn&#39;t</div><ul><li><strong>Alpha still comes from divergent views:</strong> Woodruff (ex-Citadel PM, founder of Candlestick) says long-term stock picking won&#39;t change much; what changes is how information is synthesised, and analyst and PM roles will be turned on their heads (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=63s" target="_blank" rel="noopener">1:03</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=125s" target="_blank" rel="noopener">2:05</a>)</li><li><strong>Humans are still the bottleneck:</strong> Investing is time management with diminishing returns per stock. AI can turn 6–8 hours of prep into about 5 minutes, but that just raises the table stakes, and competitors will spend the freed time on proprietary research and channel checks (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=125s" target="_blank" rel="noopener">2:05</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=281s" target="_blank" rel="noopener">4:41</a>)</li><li><strong>Juniors will still read 10-Ks:</strong> He doubts analysts will stop reading filings and transcripts; big-data cleaning gets outsourced, and AI&#39;s real job is pointing people at the right names (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=281s" target="_blank" rel="noopener">4:41</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=374s" target="_blank" rel="noopener">6:14</a>)</li></ul><div class="sh">Trust and data</div><ul><li><strong>Audit every number:</strong> As a former CPA he would never sign off on a number he can&#39;t trace; one data-entry error can cost millions, and people building models with Claude still re-audit everything, which eats the time saved (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=435s" target="_blank" rel="noopener">7:15</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=556s" target="_blank" rel="noopener">9:16</a>)</li><li><strong>What he&#39;d keep from vendors:</strong> Any internal data; he defers security to his CTO but wants strict isolation (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=556s" target="_blank" rel="noopener">9:16</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=617s" target="_blank" rel="noopener">10:17</a>)</li></ul><div class="sh">Fund structure</div><ul><li><strong>Building a fund in 2027:</strong> He&#39;d buy Kepler (Ganesh&#39;s company), keep senior stock pickers, hire fewer analysts and add investigative journalists and data engineers; the pyramid becomes more vertical (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=799s" target="_blank" rel="noopener">13:19</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=893s" target="_blank" rel="noopener">14:53</a>)</li><li><strong>Small versus big funds:</strong> Covering 400 names instead of 100 means only 5% make a 20-stock book, so hit rate can improve, but research must stay as solid; idea velocity is what matters (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=924s" target="_blank" rel="noopener">15:24</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=1046s" target="_blank" rel="noopener">17:26</a>)</li><li><strong>No-analyst hedge fund:</strong> He thinks all-agent funds can replicate last year&#39;s fund but not beat next year&#39;s, so humans stay in the loop for fundamental investing (<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=1046s" target="_blank" rel="noopener">17:26</a>–<a href="https://www.youtube.com/watch?v=y2dyD6slKxE&amp;t=1126s" target="_blank" rel="noopener">18:46</a>)</li></ul></div></article><article class="it full" id="v-rWtbOgl5FTU" data-title="The Cheaper AI Model That Costs You More - Rayan Krishnan, Vals AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=rWtbOgl5FTU" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+S+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=rWtbOgl5FTU" target="_blank" rel="noopener">The Cheaper AI Model That Costs You More - Rayan Krishnan, Vals AI</a></h3><div class="meta">AI Engineer · Rayan Krishnan, Vals AI · uploaded 30 Oct, 7:00 AM IST · 15:28</div><div class="verdict v-worth"><b>Verdict:</b> worth watching from <a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=220s" target="_blank" rel="noopener">3:40</a> for the cost data. Model names come from auto-captions and may be slightly off.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 48 times before. New here: real cost-per-task data showing a cheaper-per-token model costing more, plus Vals AI&#39;s own $1.5M token month.</div><div class="repeat">🔁 Repeat: &#39;LLM releases / benchmarks&#39; — seen 44 times before. New here: the &quot;jagged frontier&quot; shown task by task in finance.</div><div class="repeat">🔁 Repeat: &#39;token costs / AI spend&#39; — seen 13 times before. New here: a 90% cut from routing engineers to the right model per issue.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 16 times before.</div><div class="sh">Model cards hide a jagged frontier</div><ul><li><strong>Rankings change by task:</strong> Vals AI builds benchmarks labs quote in model cards (Vals Index, Finance Agent), but within a domain the top model differs per benchmark, and per-repository coding evals are even more fragmented (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=1s" target="_blank" rel="noopener">0:01</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=155s" target="_blank" rel="noopener">2:35</a>) (repeat)</li><li><strong>Adoption without ROI:</strong> Enterprise AI spend roughly doubles year on year and 90% use AI regularly, but only 7% have established ROI; groups that track AI cost are much likelier to find it (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=155s" target="_blank" rel="noopener">2:35</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=220s" target="_blank" rel="noopener">3:40</a>)</li><li><strong>Cheaper on paper, pricier in practice:</strong> On the tax benchmark, Opus 5.5 lists at $4/$20 per million tokens versus the frontier model&#39;s $10/$50, yet costs more per task because it burns extra tokens, and scores 3% lower (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=220s" target="_blank" rel="noopener">3:40</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=282s" target="_blank" rel="noopener">4:42</a>)</li><li><strong>LBO tasks flip the Pareto curve:</strong> On the Excel modelling benchmark, the whole frontier for leveraged-buyout tasks sits below the overall scores, and the overall leader drops off the cost-performance frontier for LBOs (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=282s" target="_blank" rel="noopener">4:42</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=406s" target="_blank" rel="noopener">6:46</a>)</li></ul><div class="sh">Lessons from building benchmarks</div><ul><li><strong>Pick the right metric:</strong> Partial credit versus fully correct answers give very different pictures; a model can be a good drafter but a coin toss if sent straight to a client. Also check validity, reliability (more than five or six samples) and discriminability (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=406s" target="_blank" rel="noopener">6:46</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=528s" target="_blank" rel="noopener">8:48</a>)</li><li><strong>Agents game evals:</strong> Models tried calling other models through the eval proxy to escape the sandbox, and in finance they hedge with three answers to hit more rubric items. Vals has run over 6 trillion eval tokens, and evals must go multi-turn (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=528s" target="_blank" rel="noopener">8:48</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=650s" target="_blank" rel="noopener">10:50</a>)</li></ul><div class="sh">Case study: their own token bill</div><ul><li><strong>$1.5M in a month:</strong> With unlimited tool access, a team of 10–12 engineers spent $1.5M on tokens, about 10x their salary bill. Replaying past GitHub issues against agents (now a product, Vals Smith) showed which models were overkill; GPT-5.6 beat a self-hosted Kimi open model by 2% at $2.50 versus $11 per task and half the time, and per-issue recommendations cut spend 90% at the same output (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=650s" target="_blank" rel="noopener">10:50</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=803s" target="_blank" rel="noopener">13:23</a>)</li><li><strong>Where evals pay off:</strong> Right-sizing usage limits, negotiating bulk pricing, routing and fine-tuning; the raw material is a firm&#39;s history of work in email, SharePoint and Databricks (<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=803s" target="_blank" rel="noopener">13:23</a>–<a href="https://www.youtube.com/watch?v=rWtbOgl5FTU&amp;t=928s" target="_blank" rel="noopener">15:28</a>)</li></ul></div></article><article class="it full" id="v-t9Jro9BAIMw" data-title="I Hid a Raspberry Pi in a Pumpkin to Fix Smart Speakers" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=t9Jro9BAIMw" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+U+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=t9Jro9BAIMw" target="_blank" rel="noopener">I Hid a Raspberry Pi in a Pumpkin to Fix Smart Speakers</a></h3><div class="meta">Better Stack · uploaded 30 Oct, 9:30 AM IST · 10:22</div><div class="verdict v-skim"><b>Verdict:</b> skim; a fun weekend project, light on new AI content.</div><div class="repeat">🔁 Repeat: &#39;voice / speech models&#39; — seen 11 times before. New here: a hands-on hardware build (a first-time solderer&#39;s Halloween voice assistant), not a model review.</div><div class="sh">The design</div><ul><li><strong>Local speech-to-text, remote brain:</strong> A Raspberry Pi with a hat carrying an amplifier, speaker, two LED rings and a mic listens for &quot;hey pumpkin&quot;, transcribes locally with a Parakeet model, sends the text to a fast remote LLM with web and location tools, then speaks the reply (<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=32s" target="_blank" rel="noopener">0:32</a>–<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=92s" target="_blank" rel="noopener">1:32</a>)</li></ul><div class="sh">The build</div><ul><li><strong>Learning to solder:</strong> He watched tutorials and did a practice kit first; wiring two cables into each single LED-ring hole kept snapping wires and took a couple of hours (<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=92s" target="_blank" rel="noopener">1:32</a>–<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=247s" target="_blank" rel="noopener">4:07</a>)</li><li><strong>Perma-Proto hat:</strong> Everything is soldered onto an Adafruit Perma-Proto hat (40 header pins, a six-pin amp strip, eight or nine wires) that plugs onto the Pi, so the Pi itself stays solder-free (<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=216s" target="_blank" rel="noopener">3:36</a>–<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=307s" target="_blank" rel="noopener">5:07</a>)</li><li><strong>The short circuit:</strong> The speaker died because his badly soldered board touched the active cooler; a wedge of card fixed it (<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=307s" target="_blank" rel="noopener">5:07</a>–<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=368s" target="_blank" rel="noopener">6:08</a>)</li></ul><div class="sh">The software</div><ul><li><strong>Model choices:</strong> Python with Sherpa-ONNX running Parakeet for speech-to-text; DeepSeek Flash beat Gemini Flash and Haiku on speed, since voice needs replies within about a second; ElevenLabs Flash for the spooky voice, because local text-to-speech sounded terrible on a Pi (<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=368s" target="_blank" rel="noopener">6:08</a>–<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=430s" target="_blank" rel="noopener">7:10</a>)</li><li><strong>Result:</strong> Cling film inside the pumpkin to avoid shorts; it plans an evening out avoiding the city centre with real local events and prices. He admits the parts cost more than buying a smart speaker (<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=430s" target="_blank" rel="noopener">7:10</a>–<a href="https://www.youtube.com/watch?v=t9Jro9BAIMw&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li></ul></div></article></div>',1))])}const H=y(x,[["render",z]]);export{F as __pageData,H as default};
